const cohereEmbeddingModelOptions = z.object({
	/**
	* The format of the returned embedding. Defaults to `float`.
	* Non-float formats require Embed v3.0 or newer.
	* Binary formats contain packed bytes, not individual vector dimensions.
	*/
	embeddingType: z.enum([
		"float",
		"int8",
		"uint8",
		"binary",
		"ubinary"
	]).optional(),
	/**
	* Specifies the type of input passed to the model. Default is `search_query`.
	*
	* - "search_document": Used for embeddings stored in a vector database for search use-cases.
	* - "search_query": Used for embeddings of search queries run against a vector DB to find relevant documents.
	* - "classification": Used for embeddings passed through a text classifier.
	* - "clustering": Used for embeddings run through a clustering algorithm.
	*/
	inputType: z.enum([
		"search_document",
		"search_query",
		"classification",
		"clustering"
	]).optional(),
	/**
	* Specifies how the API will handle inputs longer than the maximum token length.
	* Default is `END`.
	*
	* - "NONE": If selected, when the input exceeds the maximum input token length will return an error.
	* - "START": Will discard the start of the input until the remaining input is exactly the maximum input token length for the model.
	* - "END": Will discard the end of the input until the remaining input is exactly the maximum input token length for the model.
	*/
	truncate: z.enum([
		"NONE",
		"START",
		"END"
	]).optional(),
	/**
	* The number of dimensions of the output embedding.
	* Only available for `embed-v4.0` and newer models.
	*
	* Embed v4.0 supports `256`, `512`, `1024`, and `1536` (default).
	* Embed v5.0 Pro and Fast also support `768` and `2048` (default).
	*/
	outputDimension: z.union([
		z.literal(256),
		z.literal(512),
		z.literal(768),
		z.literal(1024),
		z.literal(1536),
		z.literal(2048)
	]).optional()
});
